export function createStockJobExpense(data:Data,input:StockJobExpenseInput):Expense {
 const job=data.jobs.find(j=>j.id===input.jobId);
 const vehicle=data.vehicles.find(v=>v.id===input.vehicleId);
 if(!job||!vehicle||vehicle.type!=='Stock / Investor'||job.vehicleId!==vehicle.id)throw new Error('Select a job belonging to the selected stock vehicle.');
 if(!input.description.trim())throw new Error('Enter an expense description.');
 if(!['Labour','Direct purchase','Other'].includes(input.costType))throw new Error('Select a valid expense type.');
 if(![input.amount,input.investor,input.capital].every(Number.isFinite)||input.amount<=0||input.investor<0||input.capital<0)throw new Error('Enter a positive expense and nonnegative funding amounts.');
 const paise=(n:number)=>Math.round(n*100);
 if([input.amount,input.investor,input.capital].some(n=>Math.abs(n*100-paise(n))>0.000001)||paise(input.investor)+paise(input.capital)!==paise(input.amount))throw new Error('Investor Fund and Company Running Capital must equal the expense amount.');
 return {id:input.id,vehicleId:vehicle.id,jobId:job.id,garageId:job.garageId,description:input.description.trim(),costType:input.costType,amount:input.amount,investor:input.investor,capital:input.capital,date:input.date,category:'Vehicle'};
}

export function requireFund(data:Data,vehicleId:string,amount:number){
 const v=data.vehicles.find(v=>v.id===vehicleId);
 if(!v||v.type!=='Stock / Investor'||!v.investorId)throw new Error('Investor Fund is unavailable for this vehicle.');
 const position=fundPosition(data,v.investorId);
 if(position.incomplete)throw new Error('Investor Fund cannot be validated until missing stock issue funding allocations are resolved.');
 if(!Number.isFinite(amount)||amount<0||Math.round(amount*100)>Math.round(position.available*100))throw new Error('Insufficient available Investor Fund. Reduce the Investor allocation or use Company Running Capital.');
}

/** Actual capital recovery is separate from income and follows investor principal recovery. */

