export function createInventoryIssue(data:Data,input:InventoryIssueInput):{issue:Issue;expense?:Expense;jobUpdate?:Data['jobs'][number]}{
 const batch=data.batches.find(row=>row.id===input.batchId),vehicle=data.vehicles.find(row=>row.id===input.vehicleId);
 if(!batch||!vehicle)throw new Error('Select an existing purchase batch and vehicle.');
 const job=input.jobId?data.jobs.find(row=>row.id===input.jobId):undefined;
 if(input.jobId&&(!job||job.vehicleId!==vehicle.id))throw new Error('Select a job belonging to the selected vehicle.');
 if(!Number.isInteger(input.quantity)||input.quantity<=0||input.quantity>remaining(data,batch)||![input.price,input.investor,input.capital].every(Number.isFinite)||input.price<=0||input.investor<0||input.capital<0)throw new Error('Enter a valid quantity, issue price and funding split.');
 const paise=(n:number)=>Math.round(n*100), total=paise(input.quantity*input.price);
 if(Math.abs(input.price*100-paise(input.price))>0.000001)throw new Error('Enter an issue price to two decimal places.');
 if(vehicle.type==='Stock / Investor'){
  if(paise(input.investor)+paise(input.capital)!==total)throw new Error('Investor Fund and Company Running Capital must equal the issue value.');
  if(input.investor>0)requireFund(data,vehicle.id,input.investor);
 }else if(input.investor!==0||input.capital!==0){
  throw new Error('Customer Vehicle stock issues cannot use Investor Fund or Running Capital.');
 }
 const issue:Issue={id:input.issueId,batchId:batch.id,vehicleId:vehicle.id,jobId:job?.id??'',expenseId:vehicle.type==='Stock / Investor'?input.expenseId:undefined,jobCostId:vehicle.type==='Customer'?input.costId:undefined,quantity:input.quantity,price:input.price,date:input.date,investor:input.investor,capital:input.capital};
 if(vehicle.type!=='Stock / Investor'){
  if(!job)throw new Error('Select an existing Garage Job for a customer vehicle stock issue.');
  const cost={id:input.costId,date:input.date,category:'Direct purchase' as const,description:`${batch.itemId} · ${input.quantity} units`,amount:input.quantity*batch.cost};
  const charge={id:input.chargeId,date:input.date,category:'Material' as const,description:`${batch.itemId} · ${input.quantity} units`,amount:input.quantity*input.price};
  return {issue,jobUpdate:{...job,costs:[...(job.costs??[]),cost],charges:[...(job.charges??[]),charge],charge:job.charge+charge.amount}};
 }
 const expense:Expense={id:input.expenseId,vehicleId:vehicle.id,jobId:job?.id,garageId:job?.garageId??batch.garageId,description:`Inventory issue · ${input.quantity} × ${input.price}`,amount:input.quantity*input.price,investor:input.investor,capital:input.capital,date:input.date,category:'Vehicle',costType:'Direct purchase'};
 return {issue,expense};
}

