export function validateSaleCorrection(data:Data,saleId:string,price:number,reason:string){
 const sale=data.sales.find(s=>s.id===saleId),vehicle=sale&&data.vehicles.find(v=>v.id===sale.vehicleId);
 if(!sale||!vehicle)throw new Error('Select an existing sale.');
 if(vehicle.type!=='Stock / Investor'||capitalContribution(data,vehicle.id)>0||paid(data,'capital',vehicle.id)>0)throw new Error('Sale correction with mixed Company capital requires manual reconciliation.');
 if(!Number.isFinite(price)||price<=0||Math.abs(price*100-Math.round(price*100))>0.000001||!reason.trim())throw new Error('Enter a positive sale price and correction reason.');
 const received=Math.round((sale.received+paid(data,'buyer',sale.id)-(data.buyerRefunds??[]).filter(r=>r.saleId===sale.id).reduce((n,r)=>n+r.amount,0))*100);
 if(Math.round(price*100)>received+Math.round(buyerRefundPayable(data,sale)*100))throw new Error('A correction cannot create an uncollected price increase.');
 return {sale,oldPrice:salePrice(sale),newPrice:price,refundPayable:Math.max(0,(received-Math.round(price*100))/100)};
}

