export function validateBuyerRefund(data:Data,saleId:string,amount:number){
 const sale=data.sales.find(s=>s.id===saleId),vehicle=sale&&data.vehicles.find(v=>v.id===sale.vehicleId);
 if(!sale||!vehicle)throw new Error('Select an existing sale.');
 if(vehicle.type!=='Stock / Investor'||capitalContribution(data,vehicle.id)>0||paid(data,'capital',vehicle.id)>0)throw new Error('Refund with mixed Company capital requires manual reconciliation.');
 const payable=Math.round(buyerRefundPayable(data,sale)*100),already=(data.buyerRefunds??[]).filter(r=>r.saleId===saleId).reduce((n,r)=>n+Math.round(r.amount*100),0);
 const recovered=(data.principalRecoveries??[]).filter(r=>r.vehicleId===vehicle.id).reduce((n,r)=>n+Math.round(r.amount*100),0);
 const returned=(data.buyerRefunds??[]).filter(r=>r.saleId===saleId).reduce((n,r)=>n+Math.round(r.principalBacked*100),0);
 const backed=Math.min(Math.round(amount*100),Math.max(0,recovered-returned));
 if(!Number.isFinite(amount)||amount<=0||Math.abs(amount*100-Math.round(amount*100))>0.000001||Math.round(amount*100)>payable||already+Math.round(amount*100)>Math.round((sale.received+paid(data,'buyer',saleId))*100))throw new Error('Refund must be positive and cannot exceed the current buyer refund payable.');
 const position=fundPosition(data,vehicle.investorId!);if(backed>Math.round(position.principal*100))throw new Error('Investor Fund cannot support the principal-backed refund.');
 return {principalBacked:backed/100,payable:payable/100};
}

