export function validateCapitalRecovery(data:Data,vehicleId:string,amount:number){
 const position=recoveryLimit(data,vehicleId);
 const vehicle=data.vehicles.find(v=>v.id===vehicleId)!;
 const sale=data.sales.find(s=>s.id===position.saleId)!;
 if(Math.round((sale.received+paid(data,'buyer',sale.id)-(data.buyerRefunds??[]).filter(r=>r.saleId===sale.id).reduce((n,r)=>n+r.amount,0))*100)!==Math.round(salePrice(sale)*100))throw new Error('Capital recovery requires full buyer collection.');
 if(Math.round(sale.price*100)<=Math.round(totalVehicleCost(data,vehicle.id)*100))throw new Error('Capital recovery requires a positive vehicle result; loss requires manual review.');
 if(Math.round(position.limit*100)>0)throw new Error('Recover the outstanding investor principal first.');
 const outstanding=Math.round(capitalContribution(data,vehicleId)*100)-Math.round(paid(data,'capital',vehicleId)*100);
 if(!Number.isFinite(amount)||amount<=0||Math.abs(amount*100-Math.round(amount*100))>0.000001||Math.round(amount*100)>outstanding)throw new Error('Capital recovery must be positive and no greater than the outstanding company contribution.');
 return {saleId:sale.id,limit:outstanding/100};
}

